def Proteins(ProteinMap, Text):
    res = ""
    for i in range(0,(len(Text) - 3) + 1, 3):
        if Text[i:i+3] in ProteinMap:
            res+=ProteinMap[Text[i:i+3]]
    return res

with open('C:/Users/Matthew/Downloads/RNA_codon_table_1.txt', 'r') as file:
    line = file.readlines()
ProteinMap = {}
for i in line:
    c = i.strip().split(" ")
    if len(c) == 2:
        ProteinMap[c[0]] = c[1]
    else:
        ProteinMap[c[0]] = ""
Text = ""
res = Proteins(ProteinMap, Text)
print(res)